const setCustomerActive = `-- name: SetCustomerActive :execrows
UPDATE customers
SET deleted_at = CASE WHEN $1::boolean THEN NULL ELSE CURRENT_TIMESTAMP END,
    deleted_by = CASE WHEN $1::boolean THEN NULL ELSE $2::uuid END,
    updated_by = $2::uuid,
    updated_at = CURRENT_TIMESTAMP
WHERE id = $3
    AND company_id = $4
`

type SetCustomerActiveParams struct {
	Active    bool        `json:"active"`
	UserID    pgtype.UUID `json:"user_id"`
	ID        pgtype.UUID `json:"id"`
	CompanyID pgtype.UUID `json:"company_id"`
}

// Inativar mantém o histórico; reativar volta o cliente para as listas
func (q *Queries) SetCustomerActive(ctx context.Context, arg SetCustomerActiveParams) (int64, error) {
	result, err := q.db.Exec(ctx, setCustomerActive,
		arg.Active,
		arg.UserID,
		arg.ID,
		arg.CompanyID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
